def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()
    expiry_times = {}
    results = []

    for op in ops:
        op_type = op[0]
        current_time = op[1]
        key = op[2]

        # Remove expired entries
        expired_keys = [k for k, exp_time in expiry_times.items() if exp_time <= current_time]
        for k in expired_keys:
            if k in cache:
                del cache[k]
            del expiry_times[k]

        if op_type == 'put':
            value = op[3]

            # If key already exists, remove it to re-insert it as most recent
            if key in cache:
                del cache[key]
            # If cache is at capacity and key is new, evict LRU
            elif len(cache) >= capacity:
                lru_key, _ = cache.popitem(last=False)
                del expiry_times[lru_key]

            # Add the entry
            cache[key] = value
            expiry_times[key] = current_time + ttl

        elif op_type == 'get':
            if key in cache:
                # Move to end (most recently used)
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(-1)

    return results

